#ifndef TYPES_H
#define TYPES_H

typedef struct {
    short noi;  /* number of increases */
    short cv;   /* current value */
} counter_state_t;

typedef enum {
    COUNTER_OK       =  0,
    COUNTER_ERROR    = -1,
    COUNTER_OVERFLOW = -2
} counter_status_t;

#endif /* TYPES_H */#ifndef RNG_H
#define RNG_H

#ifndef RANGE
#error "RANGE macro is not defined"
#endif

#ifndef VAL_POS
#error "VAL_POS macro is not defined"
#endif

/** Clamps value into [-RANGE, RANGE]; if VAL_POS, into [0, RANGE]. */
short valueToBeAdded(short value);

#endif /* RNG_H */#include "rng.h"

short valueToBeAdded(short value) {
#if VAL_POS
    if (value < 0) {
        value = -value;
    }
#endif
    if (value < -RANGE) {
        return -RANGE;
    } else if (value > RANGE) {
        return RANGE;
    }
    return value;
}/*
