#include "types.h"
#include <stdio.h>

void printStatus(counter_status_t status) {
    switch (status) {
        case COUNTER_SUCCESS:
            printf("Status: Success\n");
            break;
        case COUNTER_ERROR:
            printf("Status: Error\n");
            break;
        case COUNTER_OVERFLOW:
            printf("Status: Overflow detected\n");
            break;
        default:
            printf("Status: Unknown\n");
            break;
    }
}

